请对以下 case 进行三维加权评分。

=== case_id ===
Case-03-003

=== 用户原始指令 (query.txt) ===
帮我做个抖音防沉迷卡片放桌面，顶部显示应用使用时长监控标题，中间横向进度条展示今日使用进度，正常部分和超出设定值的部分用不同颜色区分，橙色部分代表超出的时长，中间还要显示每日使用具体参数比如总时长和超出了多少，底部一个按钮点进去能重新设置每日使用时长上限，直接跳到系统设置里改。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我做个抖音防沉迷卡片放桌面，顶部显示应用使用时长监控标题，中间横向进度条展示今日使用进度，正常部分和超出设定值的部分用不同颜色区分，橙色部分代表超出的时长，中间还要显示每日使用具体参数比如总时长和超出了多少，底部一个按钮点进去能重新设置每日使用时长上限，直接跳到系统设置里改。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "parent_control"
      }
    }
  ],
  "dataModel": {
    "value": {
      "antiAddiction": {
        "title": "应用使用时长监控",
        "appName": "抖音",
        "todayUsageText": "今日已用 2小时35分",
        "dailyLimitText": "每日上限 2小时",
        "overLimitText": "已超出 35分钟",
        "normalRatio": 77,
        "overRatio": 23,
        "actionText": "重新设置上限"
      }
    }
  },
  "assetCandidates": []
}

